// 2) Your own async iterator — e.g. paging an upstream API lazily
static async IAsyncEnumerable<OrderDto> FetchAllOrders(
    IOrdersApiClient api,
    [EnumeratorCancellation] CancellationToken ct = default)   // wires WithCancellation
{
    string? cursor = null;
    do
    {
        var page = await api.GetPageAsync(cursor, ct);         // awaited per page
        foreach (var order in page.Items)
            yield return order;                                // consumer pulls one by one

        cursor = page.NextCursor;
    } while (cursor is not null);
    // consumer stopped early? disposal unwinds here — no further pages are fetched
}

// 3) Consumption — including early break and cancellation
var options = new EnumerationOptions { MaxCount = 5_000 };   // stop after 5k
await foreach (var order in FetchAllOrders(api, ct)
    .WithCancellation(ct)
    .Take(5_000))                                            // from System.Linq.Async
{
    await ProcessAsync(order, ct);
}

// 4) Bounded batches — often better than one giant stream
static async IAsyncEnumerable<List<OrderDto>> BatchAsync(
    IAsyncEnumerable<OrderDto> source, int size,
    [EnumeratorCancellation] CancellationToken ct = default)
{
    var batch = new List<OrderDto>(size);
    await foreach (var item in source.WithCancellation(ct))
    {
        batch.Add(item);
        if (batch.Count == size)
        {
            yield return batch;
            batch = new List<OrderDto>(size);
        }
    }
    if (batch.Count > 0) yield return batch;
}

